package br.com.lealinfo.vidraceiro;
import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;
/** Inspects the actual native Home tree, captures scroll and full rendered content. */
final class HomeFidelityFlow {
 static void inspect(MeasureFlowInstrumentation t,View v){if(v instanceof TextView){TextView text=(TextView)v;if(text.getLayout()!=null){for(int line=0;line<text.getLayout().getLineCount();line++)t.check(text.getLayout().getEllipsisCount(line)==0,"Home text not ellipsized: "+text.getText());t.check(text.getLayout().getHeight()<=text.getHeight()-text.getPaddingTop()-text.getPaddingBottom()+2,"Home text fits: "+text.getText());}}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)inspect(t,g.getChildAt(i));}}
 static void capture(MeasureFlowInstrumentation t)throws Exception{MainActivity a=t.a;t.ui(()->a.home());String size=a.getResources().getConfiguration().screenWidthDp+"dp-"+a.getResources().getDisplayMetrics().densityDpi+"dpi";t.ui(()->{inspect(t,a.root);View first=t.find(a.root,"Orçamentos"),second=t.find(a.root,"Clientes");View c1=(View)first.getParent(),c2=(View)second.getParent();t.check(c1.getParent()==c2.getParent()&&c1.getLeft()<c2.getLeft(),"real two-column card layout "+size);});t.screenshot("home-top-"+size);t.ui(()->a.scroll.smoothScrollTo(0,a.px(420)));Thread.sleep(600);t.screenshot("home-middle-"+size);t.ui(()->a.scroll.fullScroll(View.FOCUS_DOWN));Thread.sleep(600);t.screenshot("home-bottom-"+size);t.ui(()->{Bitmap b=Bitmap.createBitmap(a.root.getWidth(),a.root.getHeight(),Bitmap.Config.ARGB_8888);a.root.draw(new Canvas(b));try(FileOutputStream out=new FileOutputStream(new File(a.getFilesDir(),"home-full-"+size+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();a.scroll.scrollTo(0,0);});}
}
